import React, { useState, useEffect } from "react";
import { db } from "../../firebaseConfig";
import { collection, query, where, getDocs } from "firebase/firestore";
import { useNavigate } from "react-router-dom";
import "./ExamPage.css";

const ExamPage = ({ studentClass }) => {
  const [subjects, setSubjects] = useState([]);
  const [selectedSubject, setSelectedSubject] = useState("");
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  // Default subjects for Nigerian schools
  const defaultSubjects = [
    "Mathematics",
    "English Language",
    "Biology",
    "Physics",
    "Chemistry",
    "Economics",
    "Geography",
    "History",
    "Government",
    "Agricultural Science",
    "Commerce",
    "Literature in English",
    "Computer Science",
    "Further Mathematics",
    "Civic Education",
    "Religious Studies",
    "French",
    "Physical Education",
    "Music",
    "Fine Arts",
    "Technical Drawing",
    "Home Economics"
  ];

  useEffect(() => {
    const fetchSubjects = async () => {
      setLoading(true);
      try {
        const q = query(
          collection(db, "exams"),
          where("classLevel", "==", studentClass)
        );
        const querySnapshot = await getDocs(q);
        const fetchedSubjects = querySnapshot.docs.map((doc) => doc.data().subject);

        // Combine default subjects with subjects from the database
        const combinedSubjects = Array.from(new Set([...defaultSubjects, ...fetchedSubjects]));
        setSubjects(combinedSubjects);
      } catch (error) {
        console.error("Error fetching subjects:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchSubjects();
  }, [studentClass]);

  const handleSubjectSelection = (e) => {
    setSelectedSubject(e.target.value);
  };

  const startExam = () => {
    if (selectedSubject) {
      navigate(`/exam/${selectedSubject}`);
    } else {
      alert("Please select a subject.");
    }
  };

  return (
    <div className="exam-page">
      <h2>Select an Exam Subject</h2>
      {loading ? (
        <p>Loading subjects...</p>
      ) : (
        <>
          <select
            className="subject-dropdown"
            value={selectedSubject}
            onChange={handleSubjectSelection}
          >
            <option value="">Select a subject</option>
            {subjects.map((subject, index) => (
              <option key={index} value={subject}>
                {subject}
              </option>
            ))}
          </select>
          <button
            onClick={startExam}
            className="start-exam-btn"
            disabled={!selectedSubject}
          >
            Start Exam
          </button>
        </>
      )}
    </div>
  );
};

export default ExamPage;
